namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnWorkflow _returnWorkflow;
    private readonly ReturnabilityPolicy _returnabilityPolicy;
    private readonly RefundCalculator _refundCalculator;
    private readonly RefundJournal _refundJournal;
    private readonly Restocker _restocker;

    public ReturnsHandler()
    {
        var registry = new ReturnRegistry();
        var restockLedger = new RestockLedger();
        _refundJournal = new RefundJournal();
        _returnWorkflow = new ReturnWorkflow(registry, restockLedger);
        _returnabilityPolicy = new ReturnabilityPolicy(registry);
        _refundCalculator = new RefundCalculator(_refundJournal);
        _restocker = new Restocker(restockLedger);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _returnWorkflow.Process(order, customer);

    public bool IsReturnable(Order order) =>
        _returnabilityPolicy.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refundCalculator.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refundJournal.Log(order, amount);

    public int Restock(Order order) =>
        _restocker.Restock(order);

    private sealed class ReturnRegistry
    {
        private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);

        public bool Contains(string reference) => _processedReferences.Contains(reference);

        public void Add(string reference) => _processedReferences.Add(reference);
    }

    private sealed class RestockLedger
    {
        private readonly Dictionary<string, int> _quantitiesBySku = new(StringComparer.Ordinal);

        public int Count => _quantitiesBySku.Count;

        public void Add(string sku, int quantity)
        {
            _quantitiesBySku[sku] = _quantitiesBySku.TryGetValue(sku, out var current)
                ? current + quantity
                : quantity;
        }

        public bool TryGetValue(string sku, out int quantity) =>
            _quantitiesBySku.TryGetValue(sku, out quantity);

        public void Set(string sku, int quantity) => _quantitiesBySku[sku] = quantity;
    }

    private sealed class ReturnWorkflow
    {
        private readonly ReturnRegistry _registry;
        private readonly RestockLedger _restockLedger;

        public ReturnWorkflow(ReturnRegistry registry, RestockLedger restockLedger)
        {
            _registry = registry;
            _restockLedger = restockLedger;
        }

        public string Process(Order order, Customer customer)
        {
            if (string.IsNullOrEmpty(order.Reference))
                return "missing reference";
            if (_registry.Contains(order.Reference))
                return "already processed";
            if (order.Lines.Count == 0)
                return "nothing to return";
            if (customer.Tier == CustomerTier.Blocked)
                return "customer blocked";

            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (line.Quantity > 100)
                    return "quantity too high";
                _restockLedger.Add(line.Sku, line.Quantity);
            }

            if (_restockLedger.Count == 0)
                return "no returnable lines";
            _registry.Add(order.Reference);
            return "accepted";
        }
    }

    private sealed class ReturnabilityPolicy
    {
        private readonly ReturnRegistry _registry;

        public ReturnabilityPolicy(ReturnRegistry registry)
        {
            _registry = registry;
        }

        public bool IsReturnable(Order order)
        {
            if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
                return false;
            if (_registry.Contains(order.Reference))
                return false;

            int valid = 0;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (string.IsNullOrEmpty(line.Sku))
                    continue;
                if (line.Quantity > 100)
                    continue;
                if (line.Quantity >= 1 && line.Quantity <= 100)
                    valid++;
            }

            return valid > 0;
        }
    }

    private sealed class RefundCalculator
    {
        private const decimal UnitRefund = 5m;
        private readonly RefundJournal _journal;

        public RefundCalculator(RefundJournal journal)
        {
            _journal = journal;
        }

        public decimal Compute(Order order)
        {
            decimal refund = 0m;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (line.Quantity > 50)
                    refund += line.Quantity * UnitRefund * 0.9m;
                else if (line.Quantity > 10)
                    refund += line.Quantity * UnitRefund * 0.95m;
                else if (line.Quantity > 1)
                    refund += line.Quantity * UnitRefund;
                else
                    refund += UnitRefund;
            }

            if (_journal.Count > 1000 && refund > 0m)
                refund = Math.Min(refund, 10000m);
            if (refund > 5000m)
                refund *= 0.99m;
            return refund < 0m ? 0m : refund;
        }
    }

    private sealed class RefundJournal
    {
        private readonly List<string> _entries = new();

        public int Count => _entries.Count;

        public void Log(Order order, decimal amount)
        {
            if (amount <= 0m)
                return;
            if (string.IsNullOrEmpty(order.Reference))
                return;
            if (_entries.Count == 0 || amount > 100m)
                _entries.Add($"{order.Reference}:{amount}");
            else if (amount > 50m)
                _entries.Add($"{order.Reference}:large:{amount}");
            else if (amount > 10m)
                _entries.Add($"{order.Reference}:mid:{amount}");
            else
                _entries.Add($"{order.Reference}:small:{amount}");
            if (_entries.Count > 500 && amount > 1000m)
                _entries.Add($"{order.Reference}:flag");
        }
    }

    private sealed class Restocker
    {
        private readonly RestockLedger _ledger;

        public Restocker(RestockLedger ledger)
        {
            _ledger = ledger;
        }

        public int Restock(Order order)
        {
            int moved = 0;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                var sku = line.Sku;
                if (string.IsNullOrEmpty(sku))
                    continue;
                if (line.Quantity > 100)
                    continue;
                if (_ledger.TryGetValue(sku, out var pending) && pending > 0)
                {
                    moved += pending;
                    _ledger.Set(sku, 0);
                }
                else if (line.Quantity > 50)
                {
                    _ledger.Set(sku, line.Quantity / 2);
                }
                else if (line.Quantity > 0)
                {
                    _ledger.Set(sku, line.Quantity);
                }
                if (moved > 100000)
                    break;
            }

            return moved;
        }
    }
}
